#!/usr/bin/env python3
"""
Generate a valid 15x15 crossword puzzle.
Uses system dictionary solver, then outputs complete validated JSON.
"""

import json
import sys
import time
import random
from collections import defaultdict

PATTERN = [
    "....#....#.....",
    "....#....#.....",
    "....#....#.....",
    "###.....#......",
    ".....##....####",
    "...#......#....",
    ".......#.......",
    ".......#.......",
    ".......#.......",
    "....#......#...",
    "####....##.....",
    "......#.....###",
    ".....#....#....",
    ".....#....#....",
    ".....#....#....",
]

slots = []
for r in range(15):
    c = 0
    while c < 15:
        if PATTERN[r][c] == '.':
            s = c
            while c < 15 and PATTERN[r][c] == '.': c += 1
            if c-s >= 3:
                slots.append(('A', [(r, s+i) for i in range(c-s)]))
        else: c += 1
for col in range(15):
    r = 0
    while r < 15:
        if PATTERN[r][col] == '.':
            s = r
            while r < 15 and PATTERN[r][col] == '.': r += 1
            if r-s >= 3:
                slots.append(('D', [(s+i, col) for i in range(r-s)]))
        else: r += 1

print(f"Total slots: {len(slots)}")

# Load ALL words from system dict (lowercase only, no proper nouns)
all_words = set()
with open("/usr/share/dict/words") as f:
    for line in f:
        w = line.strip()
        if w.isalpha() and w.islower() and 3 <= len(w) <= 7:
            all_words.add(w.upper())

