for w in common_text:
    w = w.strip().upper()
    if w.isalpha() and 3 <= len(w) <= 7:
        COMMON.add(w)

print(f"Common words: {len(COMMON)}")

words_by_len = defaultdict(list)
for w in all_words:
    words_by_len[len(w)].append(w)

# Pre-index
word_index = defaultdict(set)
for n, wlist in words_by_len.items():
    for w in wlist:
        for i, ch in enumerate(w):
            word_index[(n, i, ch)].add(w)

# Crossing map
cell_to_slots = defaultdict(list)
for i, (d, cells) in enumerate(slots):
    for j, (r, c) in enumerate(cells):
        cell_to_slots[(r,c)].append((i, j))

crossings = defaultdict(list)
for i, (d, cells) in enumerate(slots):
    for j, (r, c) in enumerate(cells):
        for other_idx, other_pos in cell_to_slots[(r,c)]:
            if other_idx != i:
                crossings[i].append((j, other_idx, other_pos))

best_solution = None
best_common_count = 0

def run_solver(seed):
    global best_solution, best_common_count
    random.seed(seed)
    grid = {}
    used_words = set()
    slot_assignment = [None] * len(slots)

    def get_candidates(slot_idx):
        _, cells = slots[slot_idx]
        n = len(cells)
        candidates = None
        for j, (r, c) in enumerate(cells):
            if (r, c) in grid:
                letter = grid[(r, c)]
                key = (n, j, letter)
                matching = word_index.get(key, set())
                if candidates is None:
                    candidates = set(matching)
                else:
                    candidates &= matching
        if candidates is None:
            candidates = set(words_by_len[n])
        candidates -= used_words
        return list(candidates)

    def solve():
        filled = sum(1 for s in slot_assignment if s is not None)
        if filled == len(slots):
            return True
        best_s = None
        best_c = float('inf')
        best_cands = None
        for i in range(len(slots)):
            if slot_assignment[i] is not None: continue
            cands = get_candidates(i)
            if not cands: return False
            if len(cands) < best_c:
                best_c = len(cands)
                best_s = i
                best_cands = cands
                if best_c == 1: break

        random.shuffle(best_cands)
        best_cands.sort(key=lambda w: 0 if w in COMMON else 1)

        for word in best_cands:
            _, cells = slots[best_s]
            old_grid = {}
            for j, (r, c) in enumerate(cells):
                old_grid[(r,c)] = grid.get((r,c))
                grid[(r,c)] = word[j]
            slot_assignment[best_s] = word
            used_words.add(word)

            valid = True
            for my_pos, other_idx, other_pos in crossings[best_s]:
                if slot_assignment[other_idx] is not None: continue
                letter = word[my_pos]
                other_len = len(slots[other_idx][1])
                key = (other_len, other_pos, letter)
                if key not in word_index:
                    valid = False; break
                has_any = False
                for ow in word_index[key]:
                    if ow in used_words: continue
                    ok = True
                    for oj, (or_, oc) in enumerate(slots[other_idx][1]):
                        if (or_, oc) in grid and grid[(or_, oc)] != ow[oj]:
                            ok = False; break
                    if ok: has_any = True; break
                if not has_any:
                    valid = False; break

            if valid and solve():
                return True

            used_words.discard(word)
            slot_assignment[best_s] = None
            for (r,c), v in old_grid.items():
                if v is None:
                    if (r,c) in grid: del grid[(r,c)]
                else: grid[(r,c)] = v
        return False

    import signal
    signal.signal(signal.SIGALRM, lambda s, f: (_ for _ in ()).throw(KeyboardInterrupt))
    signal.alarm(15)
    try:
        if solve():
            words = [slot_assignment[i] for i in range(len(slots))]
            c_count = sum(1 for w in words if w in COMMON)
            if c_count > best_common_count:
                best_common_count = c_count
                best_solution = (dict(grid), list(words), [s for s in slots])
            return c_count
    except KeyboardInterrupt:
        return -1
    finally:
        signal.alarm(0)
    return -2

# Search for best solution
print("\nSearching for best solution...")
for seed in range(50):
    t0 = time.time()
    result = run_solver(seed)
    elapsed = time.time() - t0
    if result > 0:
        print(f"  Seed {seed:2d}: {result}/78 common ({elapsed:.1f}s) {'*** BEST' if result == best_common_count else ''}")
    elif result == -1:
        pass  # timeout, skip printing
    if best_common_count >= 70:
        break

if not best_solution:
    print("No solution found")
    sys.exit(1)

grid_d, words, slot_list = best_solution
print(f"\nBest solution: {best_common_count}/78 common words")

# Build grid 2D
grid_2d = []
for r in range(15):
    row = []
    for c in range(15):
        if PATTERN[r][c] == '#':
            row.append('#')
        else:
            row.append(grid_d.get((r,c), '?'))
    grid_2d.append(row)

# Print grid
print("\nGrid:")
for r in range(15):
    print("  " + " ".join(grid_2d[r]))

# Identify non-common words
non_common = [w for w in words if w not in COMMON]
print(f"\nNon-common words ({len(non_common)}):")
for w in sorted(set(non_common)):
    print(f"  {w}")

# Assign clue numbers and extract word info
print("\n=== CLUE NUMBER ASSIGNMENT ===")
clue_num = 0
across_clues = []
down_clues = []
numbered = {}

for r in range(15):
    for c in range(15):
        if PATTERN[r][c] == '#':
            continue
        is_a = False
        is_d = False
        # Check if this starts an across word
        if (c == 0 or PATTERN[r][c-1] == '#'):
            # Count length
            length = 0
            cc = c
            while cc < 15 and PATTERN[r][cc] != '#':
                length += 1
                cc += 1
            if length >= 3:
                is_a = True
        # Check if this starts a down word
        if (r == 0 or PATTERN[r-1][c] == '#'):
            length = 0
            rr = r
            while rr < 15 and PATTERN[rr][c] != '#':
                length += 1
                rr += 1
            if length >= 3:
                is_d = True

        if is_a or is_d:
            clue_num += 1
            numbered[(r,c)] = clue_num
            if is_a:
                word = ""
                cc = c
                while cc < 15 and PATTERN[r][cc] != '#':
                    word += grid_2d[r][cc]
                    cc += 1
                across_clues.append({"number": clue_num, "answer": word, "row": r, "col": c})
            if is_d:
                word = ""
                rr = r
                while rr < 15 and PATTERN[rr][c] != '#':
                    word += grid_2d[rr][c]
                    rr += 1
                down_clues.append({"number": clue_num, "answer": word, "row": r, "col": c})

print(f"Total clue numbers: {clue_num}")
print(f"Across clues: {len(across_clues)}")
print(f"Down clues: {len(down_clues)}")

# Verify sequential numbering
nums = sorted(set(e["number"] for e in across_clues + down_clues))
expected = list(range(1, len(nums)+1))
assert nums == expected, f"Non-sequential: {nums}"

# Print all words with numbers
print("\nACROSS:")
for e in across_clues:
    mark = "" if e["answer"] in COMMON else " *"
    print(f"  {e['number']:2d}. {e['answer']}{mark}")

print("\nDOWN:")
for e in down_clues:
    mark = "" if e["answer"] in COMMON else " *"
    print(f"  {e['number']:2d}. {e['answer']}{mark}")

# Save for clue writing
with open("/tmp/puzzle_words.json", "w") as f:
    json.dump({"across": across_clues, "down": down_clues, "grid": grid_2d}, f, indent=2)
print("\nSaved to /tmp/puzzle_words.json")
